/**
 * Regular expression that matches a UUID.
 */
const uuidPattern = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/;

/**
 * Generate a v4 UUID or its shortened version.
 * @param {'short' | 'shorter' | number} [length] Length.
 * @returns {string} UUID like `10f95178-c983-4cfe-91d6-4e62c8c7e582`.
 * @see https://developer.mozilla.org/en-US/docs/Web/API/Crypto/randomUUID
 */
const generateUUID = (length) => {
  const uuid = globalThis.crypto.randomUUID();

  // Last 12 characters
  if (length === 'short') {
    return /** @type {string} */ (uuid.split('-').pop());
  }

  // First 8 characters
  if (length === 'shorter') {
    return /** @type {string} */ (uuid.split('-').shift());
  }

  // First X characters but without hyphens
  if (typeof length === 'number') {
    return uuid.split('-').join('').slice(0, length);
  }

  return uuid;
};

/**
 * RFC 4648 Base32 alphabet, lowercased.
 */
const base32Alphabet = 'abcdefghijklmnopqrstuvwxyz234567';

/* eslint-disable no-bitwise */
/**
 * Encode the given bytes as a lowercase RFC 4648 Base32 string without padding.
 * @param {Uint8Array} bytes Bytes to encode.
 * @returns {string} Encoded string.
 */
const encodeBase32 = (bytes) => {
  let output = '';
  let buffer = 0;
  let bits = 0;

  bytes.forEach((byte) => {
    buffer = (buffer << 8) | byte;
    bits += 8;

    while (bits >= 5) {
      bits -= 5;
      output += base32Alphabet[(buffer >>> bits) & 31];
    }
  });

  // Always true for 16-byte UUID input, which leaves 3 bits over
  /* v8 ignore else */
  if (bits > 0) {
    output += base32Alphabet[(buffer << (5 - bits)) & 31];
  }

  return output;
};
/* eslint-enable no-bitwise */

/**
 * Generate a random ID.
 * @returns {string} Generated 26-character string.
 */
const generateRandomId = () => encodeBase32(Uint8Array.fromHex(generateUUID().replaceAll('-', '')));

/**
 * Get the SHA hash of the given file or text.
 * @param {File | Blob | ArrayBuffer | ArrayBufferView | string} input File or text.
 * @param {object} [options] Options.
 * @param {'SHA-1' | 'SHA-256' | 'SHA-512'} [options.algorithm] Digest algorithm. Default: SHA-1.
 * @param {'hex' | 'binary'} [options.format] Hash format. Default: hex.
 * @returns {Promise<string>} Hash.
 * @see https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto/digest
 */
const getHash = async (input, { algorithm = 'SHA-1', format = 'hex' } = {}) => {
  /** @type {BufferSource} */
  let data;

  // `digest()` accepts any `BufferSource`, so views are passed as-is. Slicing `view.buffer` would
  // copy the whole payload first, doubling peak memory for large inputs.
  if (typeof input === 'string') {
    data = new TextEncoder().encode(input);
  } else if (input instanceof ArrayBuffer || ArrayBuffer.isView(input)) {
    data = /** @type {BufferSource} */ (input);
  } else if (input && typeof (/** @type {any} */ (input).arrayBuffer) === 'function') {
    // Blob or File
    data = await /** @type {Blob} */ (input).arrayBuffer();
  } else {
    throw new Error('Unsupported input type for getHash');
  }

  const digest = await globalThis.crypto.subtle.digest(algorithm, data);

  if (format === 'binary') {
    return Array.from(new Uint8Array(digest), (b) => String.fromCharCode(b)).join('');
  }

  return new Uint8Array(digest).toHex();
};

export { generateRandomId, generateUUID, getHash, uuidPattern };
