  box-shadow: 0 8px 16px var(--sui-popup-shadow-color);
  -webkit-backdrop-filter: blur(16px);
  backdrop-filter: blur(16px);
  transition-property: opacity, transform;
}
.content.menu {
  border-width: var(--sui-menu-border-width, 1px);
  border-style: var(--sui-menu-border-style, solid);
  border-color: var(--sui-menu-border-color, var(--sui-secondary-border-color));
  border-radius: var(--sui-menu-border-radius, 4px);
  padding: var(--sui-menu-padding, 4px);
}
.content.menu :global(.sui.menu) {
  border-width: 0;
  border-radius: 0;
  padding: 0;
  background-color: transparent;
}
.content.listbox {
  border-width: var(--sui-listbox-border-width, 1px);
  border-style: var(--sui-listbox-border-style, solid);
  border-color: var(--sui-listbox-border-color, var(--sui-secondary-border-color));
  border-radius: var(--sui-listbox-border-radius, 4px);
  padding: var(--sui-listbox-padding, 4px);
}
.content.listbox :global(.sui.listbox) {
  border-width: 0;
  border-radius: 0;
  padding: 0;
  background-color: transparent;
}
.content.tree {
  border-width: var(--sui-tree-border-width, 1px);
  border-style: var(--sui-tree-border-style, solid);
  border-color: var(--sui-tree-border-color, var(--sui-secondary-border-color));
  border-radius: var(--sui-tree-border-radius, 4px);
  padding: var(--sui-tree-padding, 4px);
}
.content.tree :global(.sui.tree) {
  margin: 0;
  border-width: 0;
  border-radius: 0;
  padding: 0;
  background-color: transparent;
}
.content.combobox {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.content.touch {
  position: static;
  border-width: 0 !important;
  border-radius: 4px !important;
  padding: 8px;
  min-width: 320px !important;
  max-width: calc(100dvw - 32px) !important;
  max-height: calc(100dvh - 32px) !important;
}
:global(dialog.open) .content.touch {
  transform: scale(100%) !important;
}
:global(dialog:not(.open)) .content.touch {
  transform: scale(90%);
}
.content.touch.combobox :global(.sui.listbox) {
  gap: 4px;
  padding: 8px 4px !important;
}
:global(dialog.open) .content {
  transition-duration: 50ms;
  opacity: 1;
  transform: translateY(2px);
}
:global(dialog:not(.open)) .content {
  transition-duration: 300ms;
  opacity: 0;
  transform: translateY(-8px);
}
.content.nested.menu {
  margin-block: calc(-1 * (var(--sui-menu-border-width, 1px) + var(--sui-menu-padding, 4px)));
}
:global(dialog.open) .content.nested.menu {
  transform: none;
}</style>
