<!--
  @component
  A code editor based on Lexical.
-->
<script>
  import { _ } from '@sveltia/i18n';
  import { setContext, untrack } from 'svelte';
  import Alert from '../alert/alert.svelte';
  import Toast from '../toast/toast.svelte';
  import { parseCodeBlock, toCodeBlock } from './code-editor.js';
  import LexicalRoot from './lexical-root.svelte';
  import { createEditorStore } from './store.svelte.js';
  import CodeEditorToolbar from './toolbar/code-editor-toolbar.svelte';

  /**
   * @import { Snippet } from 'svelte';
   */

  /**
   * @typedef {object} Props
   * @property {string} [code] Input value.
   * @property {string} [lang] Selected language.
   * @property {boolean} [pending] Whether the user has changed the code, and the editor has yet to
   * update {@link code}, which it does a moment later. Bind it to wait for the change before
   * reading the code, for example to save it. Read-only.
   * @property {boolean} [showLanguageSwitcher] Whether to show the language selector.
   * @property {boolean} [flex] Make the text input container flexible.
   * @property {string} [class] The `class` attribute on the wrapper element.
   * @property {boolean} [hidden] Whether to hide the widget.
   * @property {boolean} [disabled] Whether to disable the widget. An alias of the `aria-disabled`
   * attribute.
   * @property {boolean} [readonly] Whether to make the widget read-only. An alias of the
   * `aria-readonly` attribute.
   * @property {boolean} [required] Whether to mark the widget required. An alias of the
   * `aria-required` attribute.
   * @property {boolean} [invalid] Whether to mark the widget invalid. An alias of the
   * `aria-invalid` attribute.
   * @property {string} [ariaLabel] The `aria-label` attribute on the editable text box. Either
   * this or `ariaLabelledby` is required for the editor to have an accessible name.
   * @property {string} [ariaLabelledby] The `aria-labelledby` attribute on the editable text box.
   * @property {string} [ariaDescribedby] The `aria-describedby` attribute on the editable text
   * box.
   * @property {Snippet} [children] Primary slot content.
   */

  /**
   * @type {Props & Record<string, any>}
   */
  let {
    /* eslint-disable prefer-const */
    code = $bindable(''),
    lang = $bindable('plain'),
    pending = $bindable(false),
    showLanguageSwitcher = false,
    flex = false,
    hidden = false,
    disabled = false,
    readonly = false,
    required = false,
    invalid = false,
    ariaLabel = undefined,
    ariaLabelledby = undefined,
    ariaDescribedby = undefined,
    'aria-label': ariaLabelAttr = undefined,
    'aria-labelledby': ariaLabelledbyAttr = undefined,
    'aria-describedby': ariaDescribedbyAttr = undefined,
    children,
    ...restProps
    /* eslint-enable prefer-const */
  } = $props();

  /**
   * Labelling attributes for the editable text box. They’re pulled out of `restProps` because the
   * rest goes on the presentational wrapper, where ARIA would ignore them.
   */
  const labelAttrs = $derived({
    'aria-label': ariaLabel ?? ariaLabelAttr,
    'aria-labelledby': ariaLabelledby ?? ariaLabelledbyAttr,
    'aria-describedby': ariaDescribedby ?? ariaDescribedbyAttr,
  });

  const editorStore = createEditorStore();

  editorStore.config = {
    ...editorStore.config,
    useMarkdownShortcuts: false,
    isCodeEditor: true,
    defaultLanguage: lang,
  };

  setContext('editorStore', editorStore);

  $effect(() => {
    pending = editorStore.pending;
  });

  // An editor removed right after a change never converts it, so don’t leave a bound `pending` set
  // for good, which would hold up anything waiting for the change
  $effect(() => () => {
    pending = false;
  });

  $effect(() => {
    // The root initializes the editor before these effects first run, and stays initialized
    /* v8 ignore next */
    if (!editorStore.initialized) {
      return;
    }

    void code;
    void lang;

    untrack(() => {
      editorStore.inputValue = toCodeBlock(lang, code);
    });
  });

  $effect(() => {
    // The root initializes the editor before these effects first run, and stays initialized
    /* v8 ignore next */
    if (!editorStore.initialized) {
      return;
    }

    void editorStore.inputValue;

    untrack(() => {
      const { lang: _lang, code: _code } = parseCodeBlock(editorStore.inputValue);

      if (lang !== _lang) {
        lang = _lang;
      }

      if (code !== _code) {
        code = _code;
      }
    });
  });
</script>

<div
  {...restProps}
  role="none"
  class="sui code-editor"
  class:flex
  {hidden}
  style:--sui-text-editor-toolbar-height="{editorStore.toolbarHeight}px"
>
  {#if showLanguageSwitcher}
    <CodeEditorToolbar {disabled} {readonly} />
  {/if}
  <LexicalRoot {...labelAttrs} {hidden} {disabled} {readonly} {required} {invalid} />
</div>

{#if editorStore.showConverterError}
  <Toast bind:show={editorStore.showConverterError}>
    <Alert status="error">{_('_sui.text_editor.converter_error')}</Alert>
  </Toast>
{/if}

<style>.code-editor {
  margin: var(--sui-focus-ring-width);
  width: calc(100% - var(--sui-focus-ring-width) * 2);
}
.code-editor.flex:not([hidden]) {
  display: block;
}
.code-editor {
  --sui-text-editor-toolbar-top: var(--sui-text-editor-inner-toolbar-top, 0px);
  --sui-text-editor-toolbar-z-index: var(--sui-text-editor-inner-toolbar-z-index, 100);
}
.code-editor > :global(*) {
  --sui-text-editor-inner-toolbar-top: calc(
    var(--sui-text-editor-toolbar-top) + var(--sui-text-editor-toolbar-height)
  );
  --sui-text-editor-inner-toolbar-z-index: calc(var(--sui-text-editor-toolbar-z-index) - 1);
}</style>
