<script>
  import { _ } from '@sveltia/i18n';
  import { unique } from '@sveltia/utils/array';
  import { getContext } from 'svelte';
  import ButtonGroup from '../../button/button-group.svelte';
  import Button from '../../button/button.svelte';
  import Divider from '../../divider/divider.svelte';
  import Spacer from '../../divider/spacer.svelte';
  import Icon from '../../icon/icon.svelte';
  import MenuButton from '../../menu/menu-button.svelte';
  import Menu from '../../menu/menu.svelte';
  import { AVAILABLE_BUTTONS, BLOCK_BUTTON_TYPES, INLINE_BUTTON_TYPES } from '../constants.js';
  import { isInlineComponent } from '../core.js';
  import CodeLanguageSwitcher from './code-language-switcher.svelte';
  import AlignMenuButton from './align-menu-button.svelte';
  import FormatTextButton from './format-text-button.svelte';
  import InsertHorizontalRuleButton from './insert-horizontal-rule-button.svelte';
  import InsertItemButton from './insert-item-button.svelte';
  import InsertLinkButton from './insert-link-button.svelte';
  import InsertMenuButton from './insert-menu-button.svelte';
  import InsertTableButton from './insert-table-button.svelte';
  import TableActionMenu from './table-action-menu.svelte';
  import ToggleBlockMenuItem from './toggle-block-menu-item.svelte';
  import ToolbarWrapper from './toolbar-wrapper.svelte';

  /**
   * @import { TextEditorBlockType, TextEditorInlineType, TextEditorStore } from '../../../typedefs.js';
   */

  /**
   * @typedef {object} Props
   * @property {boolean} [hidden] Whether to hide the widget.
   * @property {boolean} [disabled] Whether to disable the widget. An alias of the `aria-disabled`
   * attribute.
   * @property {boolean} [readonly] Whether to make the widget read-only. An alias of the
   * `aria-readonly` attribute.
   */

  /**
   * @type {Props & Record<string, any>}
   */
  let {
    /* eslint-disable prefer-const */
    disabled = false,
    readonly = false,
    /* eslint-enable prefer-const */
  } = $props();

  /** @type {TextEditorStore} */
  const editorStore = getContext('editorStore');

  /**
   * Enabled block level buttons.
   * @type {TextEditorBlockType[]}
   */
  const blockLevelButtons = $derived(
    unique([
      'paragraph', // Always needed
      ...editorStore.config.enabledButtons.filter((type) =>
        BLOCK_BUTTON_TYPES.includes(/** @type {any} */ (type)),
      ),
    ]),
  );

  const isHtml = $derived(editorStore.config.format === 'html');
  /**
   * Whether the formatting buttons are available. They insert Markdown syntax in the plain text
   * mode, so they’re hidden while the HTML source is edited.
   */
  const canFormat = $derived(editorStore.useRichText || !isHtml);

  const hasTable = $derived(editorStore.config.enabledButtons.includes('table'));
  /**
   * Whether the alignment menu is available. Markdown has no syntax for alignment, so it’s only
   * available for HTML, and only in the rich text mode, as the plain text mode shows the source.
   */
  const canAlign = $derived(
    isHtml && editorStore.useRichText && editorStore.config.enabledButtons.includes('align'),
  );
  const hasHorizontalRule = $derived(editorStore.config.enabledButtons.includes('horizontal-rule'));
  /**
   * Key of the table cell the caret is in, if any. The table menu only works with the rich text
   * editor.
   */
  const tableCellKey = $derived(
    editorStore.useRichText ? (editorStore.selection.tableCellKey ?? null) : null,
  );
  /**
   * Whether the caret is in a Markdown table cell, which can only have inline content, so neither
   * a horizontal rule nor a block editor component can be inserted.
   */
  const inMarkdownTable = $derived(!!tableCellKey && !isHtml);
  /**
   * Editor components that can be inserted at the caret: only the inline ones in a Markdown table
   * cell.
   */
  const components = $derived(
    inMarkdownTable
      ? editorStore.config.components.filter(isInlineComponent)
      : editorStore.config.components,
  );
  const buttons = $derived(components.filter(({ trigger = 'menuitem' }) => trigger === 'button'));
  const menuitems = $derived(
    components.filter(({ trigger = 'menuitem' }) => trigger === 'menuitem'),
  );
  /**
   * Whether any of the buttons to insert a table, a horizontal rule or an editor component is
   * shown.
   */
  const hasInsertButtons = $derived(
    hasTable || (!inMarkdownTable && hasHorizontalRule) || components.length > 0,
  );
  /**
   * Whether the block level styles are available.
   */
  const canChangeBlock = $derived(canFormat && !inMarkdownTable);

  /**
   * Enabled inline level buttons.
   * @type {TextEditorInlineType[]}
   */
  const inlineLevelButtons = $derived(
    unique(
      editorStore.config.enabledButtons.filter((type) =>
        INLINE_BUTTON_TYPES.includes(/** @type {any} */ (type)),
      ),
    ),
  );
</script>

<!-- Disabled while an editor component has focus, as the buttons only apply to this editor -->
<ToolbarWrapper
  disabled={disabled || readonly || editorStore.componentHasFocus}
  ariaLabel={_('_sui.text_editor.text_editor')}
>
  {#if canChangeBlock && blockLevelButtons.length > 1}
    <MenuButton
      aria-label={_('_sui.text_editor.show_text_style_options')}
      aria-controls={editorStore.controlId}
    >
      {#snippet startIcon()}
        <Icon
          name={AVAILABLE_BUTTONS[editorStore.selection.blockType]?.icon ?? 'format_paragraph'}
        />
      {/snippet}
      {#snippet popup()}
        <Menu ariaLabel={_('_sui.text_editor.text_style_options')}>
          {#each blockLevelButtons as type (type)}
            <ToggleBlockMenuItem {type} />
          {/each}
        </Menu>
      {/snippet}
    </MenuButton>
  {/if}
  <!-- The language switcher only works with the rich text editor -->
  {#if editorStore.useRichText && editorStore.selection.blockType === 'code-block'}
    <Divider orientation="vertical" />
    <CodeLanguageSwitcher />
  {:else if canFormat}
    {#if hasTable && tableCellKey}
      {#if canChangeBlock && blockLevelButtons.length > 1}
        <Divider orientation="vertical" />
      {/if}
      <MenuButton
        aria-label={_('_sui.text_editor.show_table_options')}
        aria-controls={editorStore.controlId}
      >
        {#snippet startIcon()}
          <Icon name="table_edit" />
        {/snippet}
        {#snippet popup()}
          <TableActionMenu cellKey={tableCellKey} />
        {/snippet}
      </MenuButton>
    {/if}
    {#if inlineLevelButtons.length}
      <Divider orientation="vertical" />
      <ButtonGroup>
        {#each inlineLevelButtons as type (type)}
          {#if type === 'link'}
            <InsertLinkButton />
          {:else}
            <FormatTextButton {type} />
          {/if}
        {/each}
      </ButtonGroup>
    {/if}
    {#if canAlign}
      <Divider orientation="vertical" />
      <AlignMenuButton />
    {/if}
    {#if hasInsertButtons}
      <Divider orientation="vertical" />
      {#if hasTable}
        <!-- Tables can’t be nested -->
        <InsertTableButton disabled={!!tableCellKey} />
      {/if}
      {#if hasHorizontalRule && !inMarkdownTable}
        <InsertHorizontalRuleButton />
      {/if}
      {#each buttons as button (button.id)}
        <InsertItemButton component={button} />
      {/each}
      {#if menuitems.length}
        <InsertMenuButton components={menuitems} />
      {/if}
    {/if}
  {/if}
  <Spacer flex />
  {#if editorStore.config.modes.length > 1}
    <Button
      iconic
      disabled={editorStore.hasConverterError}
      pressed={!editorStore.useRichText}
      aria-label={_(`_sui.text_editor.${isHtml ? 'edit_in_html' : 'edit_in_markdown'}`)}
      onclick={() => {
        editorStore.useRichText = !editorStore.useRichText;

        if (editorStore.useRichText) {
          editorStore.convertToLexical();
        }
      }}
    >
      {#snippet startIcon()}
        <Icon name={isHtml ? 'html' : 'markdown'} />
      {/snippet}
    </Button>
  {/if}
</ToolbarWrapper>
